"""Small shared helpers: timestamps and hashing."""
from __future__ import annotations

import hashlib
from datetime import datetime, timezone


def utcnow() -> datetime:
    return datetime.now(timezone.utc)


def iso(dt: datetime) -> str:
    """Format a datetime as RFC 3339 UTC, millisecond precision, ending in Z."""
    return dt.strftime("%Y-%m-%dT%H:%M:%S.") + f"{dt.microsecond // 1000:03d}Z"


def now_iso() -> str:
    return iso(utcnow())


def parse_iso(s: str) -> datetime:
    # s always ends in 'Z' and has millisecond precision (produced by iso()).
    body = s[:-1] if s.endswith("Z") else s
    dt = datetime.strptime(body, "%Y-%m-%dT%H:%M:%S.%f")
    return dt.replace(tzinfo=timezone.utc)


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()

"""Fixed error-code taxonomy for the gateway."""
from __future__ import annotations

ERROR_STATUS = {
    "VALIDATION_ERROR": 400,
    "INVALID_FORMAT": 400,
    "PATH_NOT_ALLOWED": 403,
    "SOURCE_NOT_FOUND": 404,
    "JOB_NOT_FOUND": 404,
    "IDEMPOTENCY_KEY_CONFLICT": 409,
    "JOB_NOT_FINISHED": 409,
    "RESULT_UNAVAILABLE": 409,
    "JOB_ALREADY_TERMINAL": 409,
    "QUEUE_FULL": 429,
}


class ApiError(Exception):
    def __init__(self, code: str, message: str, retry_after: int | None = None):
        if code not in ERROR_STATUS:
            raise ValueError(f"unknown error code: {code}")
        self.code = code
        self.message = message
        self.status_code = ERROR_STATUS[code]
        self.retry_after = retry_after
        super().__init__(message)

    def body(self) -> dict:
        return {"error": {"code": self.code, "message": self.message}}


def err(code: str, message: str, retry_after: int | None = None) -> ApiError:
    return ApiError(code, message, retry_after=retry_after)

